var _langRegistry = {};

/**
 * Registers a language definition under its primary ID and all aliases.
 *
 * @param {string} id          - Primary language identifier e.g. 'javascript'
 * @param {object} definition  - Must have { aliases: string[], tokenize: function }
 */
