    if (!id || typeof definition.tokenize !== 'function') {
        return;
    }
    _langRegistry[id.toLowerCase()] = definition;
    var aliases = definition.aliases || [];
    for (var i = 0; i < aliases.length; i++) {
        _langRegistry[aliases[i].toLowerCase()] = definition;
    }
