/**
 * Retrieves a registered language definition by ID or alias.
 * Returns null if no matching language is found.
 *
 * @param {string} id
 * @returns {object|null}
 */
function getLanguage(id) {
    if (!id) return null;
    return _langRegistry[id.toLowerCase()] || null;
}

